export function UniformShowcase(n){return`\n        <div class="uniform-grid">\n            ${n.map(n=>{const i=n.variants.map(n=>`<li>${n}</li>`).join("");return`\n            <div class="uniform-card">\n                <div class="uniform-header" data-service="${n.service}">\n                    <span class="uniform-service-badge">${n.service}</span>\n                    <h4>${n.name}</h4>\n                </div>\n                <div class="uniform-body">\n                    <p class="uniform-description">${n.description}</p>\n                    <div class="uniform-usage">\n                        <strong>Usage:</strong> ${n.usage}\n                    </div>\n                    <div class="uniform-variants">\n                        <strong>Variants:</strong>\n                        <ul>${i}</ul>\n                    </div>\n                </div>\n            </div>\n        `}).join("")}\n        </div>\n    `}